using NetArchTest.Rules;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.ArchitectureTest.LayerBoundaries;

/// <summary>
/// Enforces the Domain -> Application -> Infrastructure layering: business code (Domain
/// and Application) must never depend on technical/infrastructure details, and Domain
/// must not depend on Application either. This runs as a separate, slower suite so the
/// fast unit-test loop the team runs on every save stays untouched.
/// </summary>
public sealed class LayerBoundaryTests
{
    private static readonly System.Reflection.Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly System.Reflection.Assembly ApplicationAssembly = typeof(Application.AuthorizePayment).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_application()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOn("PaymentAuthorization.Application")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOn("PaymentAuthorization.Infrastructure")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(ApplicationAssembly)
            .Should()
            .NotHaveDependencyOn("PaymentAuthorization.Infrastructure")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(NetArchTest.Rules.TestResult result)
        => result.IsSuccessful
            ? string.Empty
            : "Layer violation found in: " + string.Join(", ", result.FailingTypeNames ?? []);
}
