namespace PaymentAuthorization.ArchitectureTest.LayerBoundaries;

/// <summary>
/// Enforces the Domain -> Application -> Infrastructure layering: business code (Domain
/// and Application) must never reach for technical/infrastructure details, whether that's
/// a reference to the Infrastructure project itself or a direct dependency on a technical
/// BCL namespace (file system, network, threading primitives, etc.) that belongs behind an
/// abstraction instead. This runs as a separate, slower suite so the fast unit-test loop the
/// team runs on every save stays untouched.
/// </summary>
public sealed class LayerBoundaryTests
{
    private static readonly System.Reflection.Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly System.Reflection.Assembly ApplicationAssembly = typeof(Application.AuthorizePayment).Assembly;

    // Technical namespaces business code must reach only through an abstraction (an
    // interface defined in Application/Domain and implemented in Infrastructure).
    private static readonly string[] TechnicalNamespaces =
    [
        "System.Net.Http",
        "System.Net.Sockets",
        "System.IO",
        "System.Data",
        "Microsoft.EntityFrameworkCore",
        "Microsoft.Data",
        "Npgsql",
        "StackExchange.Redis",
        "Microsoft.Azure",
        "Amazon",
    ];

    [Fact]
    public void Domain_does_not_depend_on_application()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOn("PaymentAuthorization.Application")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOn("PaymentAuthorization.Infrastructure")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(ApplicationAssembly)
            .Should()
            .NotHaveDependencyOn("PaymentAuthorization.Infrastructure")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_does_not_depend_on_technical_namespaces()
    {
        var result = Types.InAssembly(DomainAssembly)
            .Should()
            .NotHaveDependencyOnAny(TechnicalNamespaces)
            .GetResult();

